const double d = 1.15;

// Total of 21 points mapped to the 6 faces of a [-1, 1] 3D cube.
// Array contains 6 elements, where each index 'i' corresponds to face 'i + 1'.
double[][] dicePips = new double[][]
{
    // --- Side 1 (1 point) on Z = 1 (Front) ---
    new double[] { 0.0, 0.0, d },

    // --- Side 2 (2 points) on X = -1 (Left) ---
    // (We vary Y and Z on this face)
    new double[] { -d, -0.5, -0.5 },
    new double[] { -d,  0.5,  0.5 },

    // --- Side 3 (3 points) on Y = -1 (Bottom) ---
    // (We vary X and Z on this face)
    new double[] { -0.5, -d, -0.5 },
    new double[] {  0.0, -d,  0.0 },
    new double[] {  0.5, -d,  0.5 },

    // --- Side 4 (4 points) on Y = 1 (Top) ---
    // (We vary X and Z on this face)
    new double[] { -0.5, d, -0.5 },
    new double[] { -0.5, d,  0.5 },
    new double[] {  0.5, d, -0.5 },
    new double[] {  0.5, d,  0.5 },

    // --- Side 5 (5 points) on X = 1 (Right) ---
    // (We vary Y and Z on this face)
    new double[] { d, -0.5, -0.5 },
    new double[] { d, -0.5,  0.5 },
    new double[] { d,  0.0,  0.0 },
    new double[] { d,  0.5, -0.5 },
    new double[] { d,  0.5,  0.5 },

    // --- Side 6 (6 points) on Z = -1 (Back) ---
    // (We vary X and Y on this face in two columns)
    new double[] { -0.5, -0.5, -d },
    new double[] { -0.5,  0.0, -d },
    new double[] { -0.5,  0.5, -d },
    new double[] {  0.5, -0.5, -d },
    new double[] {  0.5,  0.0, -d },
    new double[] {  0.5,  0.5, -d }
};

private IneqTree Dice()
{
  	var ball = Ball(0, 0, 0, 1.0d, 8 );
  
  	var balls = new IneqTree();
  
  	foreach(var p in dicePips)
    {
		balls = balls | (# (x - p[0])*(x - p[0]) + (y - p[1])*(y - p[1]) + (z - p[2])*(z - p[2]) - 0.06);      
    }  
  
  	return ball & !balls;
}

public IneqMesh GetIneqMesh()
{

  
    return new IneqMesh
    {
        X0 = -1.0,
        Y0 = -1.0,
        Z0 = -1.0,
        X1 = 1.0,
        Y1 = 1.0,
        Z1 = 1.0,
        D = 0.1d,
        Boxed = false,
        IneqTree = Dice()
    };
}
